--
-- Table structure for table `lkt_admin_record`
--

DROP TABLE IF EXISTS `lkt_admin_record`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `lkt_admin_record` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int DEFAULT '0' COMMENT '商城id',
  `admin_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '管理员账号',
  `event` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '事件',
  `type` tinyint DEFAULT NULL COMMENT '类型 0:登录/退出 1:添加 2:修改 3:删除 4:导出 5:启用/禁用 6:通过/拒绝 10删除订单',
  `add_date` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '操作时间',
  `source` int NOT NULL DEFAULT '1' COMMENT '数据来源 1.管理平台  2.PC店铺',
  `mch_id` int DEFAULT '0' COMMENT '店铺id',
  `operator_id` int DEFAULT '0' COMMENT '操作人ID',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=6730 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='管理员记录表';
/*!40101 SET character_set_client = @saved_cs_client */;

