CREATE TABLE `lkt_article` (
  `Article_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '文章id',
  `store_id` int NOT NULL DEFAULT '0' COMMENT '商城id',
  `Article_title` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '文章标题',
  `Article_prompt` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '文章提示',
  `Article_imgurl` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '文章图片',
  `content` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '文章内容',
  `sort` int DEFAULT NULL COMMENT '排序',
  `add_date` timestamp NULL DEFAULT NULL COMMENT '添加时间',
  `share_num` int NOT NULL DEFAULT '0' COMMENT '分享次数',
  `total_amount` decimal(12,2) NOT NULL COMMENT '红包总金额',
  `total_num` int NOT NULL DEFAULT '0' COMMENT '红包个数',
  `wishing` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '祝福语',
  PRIMARY KEY (`Article_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='单篇文章表';
