--
-- Table structure for table `lkt_auction_promise`
--

DROP TABLE IF EXISTS `lkt_auction_promise`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `lkt_auction_promise` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '主键',
  `store_id` int DEFAULT NULL COMMENT '商城id',
  `user_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '用户id',
  `promise` decimal(12,2) DEFAULT NULL COMMENT '保证金额',
  `add_time` timestamp NULL DEFAULT NULL COMMENT '添加时间',
  `special_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '专场id',
  `trade_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '订单编号',
  `is_pay` int DEFAULT NULL COMMENT '是否成功支付 0失败,1成功',
  `is_back` int DEFAULT NULL COMMENT '是否退款成功  0-成功 1-失败',
  `is_deduction` int DEFAULT '0' COMMENT '是否扣除 0=未扣除,1=已扣除',
  `allow_back` tinyint DEFAULT '1' COMMENT '是否符合退款标准  0：不符合 1：符合',
  `recovery` int DEFAULT '0' COMMENT '回收标识',
  `type` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '支付方式',
  `address_id` int DEFAULT NULL COMMENT '收货地址id',
  `source` int DEFAULT NULL COMMENT '来源 1.小程序 2.app 3.支付宝小程序 4.头条小程序 5.百度小程序 6.pc端 7.H5',
  `back_time` timestamp NULL DEFAULT NULL COMMENT '退款时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=132 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='竞拍保证金表';
/*!40101 SET character_set_client = @saved_cs_client */;

