--
-- Table structure for table `lkt_auction_special`
--

DROP TABLE IF EXISTS `lkt_auction_special`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `lkt_auction_special` (
  `id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'id',
  `store_id` int NOT NULL COMMENT '商城id',
  `mch_id` int DEFAULT '0' COMMENT '店铺id',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '专场名称',
  `img` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '专场图片',
  `sort` int DEFAULT NULL COMMENT '排序',
  `commission` decimal(10,2) DEFAULT NULL COMMENT '佣金',
  `promise_amt` decimal(12,2) DEFAULT NULL COMMENT '保证金金额',
  `look_count` int DEFAULT '0' COMMENT '围观人数',
  `start_date` timestamp NOT NULL COMMENT '开始时间',
  `end_date` timestamp NOT NULL COMMENT '结束时间',
  `sign_end_date` timestamp NULL DEFAULT NULL COMMENT '报名截至时间',
  `is_show` int NOT NULL DEFAULT '1' COMMENT '是否显示',
  `status` int DEFAULT '1' COMMENT '1=未开始 2=进行中 3=已结束',
  `type` int DEFAULT '1' COMMENT '专场类型 1=店铺专场 2=普通专场 3=报名专场',
  `unit` int DEFAULT '1' COMMENT '起拍价默认单位 1=固定金额 2=价格百分比',
  `number` decimal(12,2) NOT NULL COMMENT '起拍价默认值',
  `mark_up_amt` decimal(12,2) NOT NULL COMMENT '默认加价金额',
  `content` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '专场预告',
  `is_settlement` int DEFAULT '0' COMMENT '是否结算 0=否 1=是',
  `recovery` int DEFAULT '0' COMMENT '回收标识',
  `add_date` timestamp NULL DEFAULT NULL COMMENT '添加时间',
  `update_date` timestamp NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='专场表';
/*!40101 SET character_set_client = @saved_cs_client */;

