--
-- Table structure for table `lkt_bbs_post`
--

DROP TABLE IF EXISTS `lkt_bbs_post`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `lkt_bbs_post` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int NOT NULL DEFAULT '0' COMMENT '商城ID',
  `forum_id` bigint DEFAULT NULL COMMENT '种草官ID',
  `category_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '分类',
  `user_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'user_id',
  `title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '帖子标题',
  `pro_ids` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '商品id，逗号分割',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '文章内容',
  `images` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '文章图片',
  `video_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '云点播视频id',
  `type` tinyint(1) DEFAULT NULL COMMENT '文章类型 0：图片 1：视频 2：图文',
  `cover_img` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '封面图',
  `videos` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '视频',
  `text` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '纯文字',
  `comment_num` int NOT NULL DEFAULT '0' COMMENT '评论数量',
  `browse_num` int NOT NULL DEFAULT '0' COMMENT '浏览数量',
  `like_num` int NOT NULL DEFAULT '0' COMMENT '点赞数',
  `collect_num` int NOT NULL DEFAULT '0' COMMENT '收藏数',
  `forward_num` int NOT NULL DEFAULT '0' COMMENT '转发数',
  `follow_num` int NOT NULL DEFAULT '0' COMMENT '关注数',
  `refuse_text` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '拒绝理由',
  `status` tinyint DEFAULT '1' COMMENT '1待审核  2审核通过 3审核未通过',
  `is_home_recommend` tinyint DEFAULT '0' COMMENT '是否为推荐 0.不是推荐 1.推荐',
  `is_hide` tinyint DEFAULT '0' COMMENT '是否隐藏 0.不隐藏 1.隐藏',
  `recycle` tinyint DEFAULT '0' COMMENT '是否删除 0.未删除 1.删除',
  `create_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=295 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='文章表';
/*!40101 SET character_set_client = @saved_cs_client */;

