DROP TABLE IF EXISTS `lkt_cashier_record`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `lkt_cashier_record` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int NOT NULL DEFAULT '0' COMMENT '商城ID',
  `mch_id` int NOT NULL DEFAULT '0' COMMENT '店铺ID',
  `money` decimal(12,2) NOT NULL COMMENT '收款金额',
  `sourceNickname` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '支持者信息',
  `out_trade_no` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '订单号',
  `transaction_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '微信支付订单号',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '状态 1.成功 2.失败',
  `add_time` timestamp NULL DEFAULT NULL COMMENT '二维码生成时间',
  `success_time` timestamp NULL DEFAULT NULL COMMENT '支付完成时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='收银台记录表';
