CREATE TABLE `lkt_currency` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `currency_code` char(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'ISO货币代码(如USD)',
  `currency_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '货币名称',
  `is_show` int NOT NULL DEFAULT '1' COMMENT '是否展示 0 不展示 1展示 ',
  `currency_symbol` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '货币符号($)',
  `recycle` int NOT NULL DEFAULT '1' COMMENT '是否删除 0 未删除 1已删除 ',
  `update_time` timestamp NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=22 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='平台货币信息';
