--
-- Table structure for table `lkt_diy`
--

DROP TABLE IF EXISTS `lkt_diy`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `lkt_diy` (
  `id` int NOT NULL AUTO_INCREMENT,
  `version` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '版本号',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '页面名称',
  `value` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '页面数据',
  `tabber_info` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '导航配置信息',
  `tab_bar` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '导航',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '备注',
  `theme_dict_code` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '主题类型code（字典code）',
  `theme_type` tinyint(1) DEFAULT '1' COMMENT '主题类型 1:系统主题 2:自定义主题',
  `add_time` int DEFAULT NULL COMMENT '添加时间',
  `update_time` int DEFAULT NULL COMMENT '更新时间',
  `status` tinyint(1) DEFAULT '0' COMMENT '是否使用',
  `type` tinyint(1) DEFAULT NULL COMMENT '页面类型',
  `is_del` tinyint(1) DEFAULT '0' COMMENT '是否删除',
  `store_id` int NOT NULL COMMENT '商城ID',
  `mch_id` int DEFAULT '0' COMMENT '店铺id',
  `cover` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '封面图',
  `lang_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT 'zh_CN' COMMENT '语言',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `store_ID_idx` (`store_id`) USING BTREE,
  KEY `status_idx` (`status`) USING BTREE,
  KEY `is_del_idx` (`is_del`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=325 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='DIY数据表';
/*!40101 SET character_set_client = @saved_cs_client */;

