--
-- Table structure for table `lkt_diy_page`
--

DROP TABLE IF EXISTS `lkt_diy_page`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `lkt_diy_page` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '页面id',
  `store_id` int NOT NULL COMMENT '商城id',
  `page_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_bin NOT NULL COMMENT '页面名称',
  `type` tinyint(1) DEFAULT NULL COMMENT '类型 1：系统页面 2：自定义页面',
  `link` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '链接',
  `page_key` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '页面对应的key',
  `image` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `page_context` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '页面内容',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '状态 0:不启用 1:启用',
  `recycle` int NOT NULL DEFAULT '0' COMMENT '是否回收 0：显示 1：回收',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '添加时间',
  `create_by` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '创建人',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=134 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='diy页面';
/*!40101 SET character_set_client = @saved_cs_client */;

