DROP TABLE IF EXISTS `lkt_group_open`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `lkt_group_open` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'id',
  `activity_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '活动id',
  `goods_id` int NOT NULL COMMENT '商品id',
  `attr_id` int NOT NULL COMMENT '规格id',
  `user_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '团长user_id',
  `team_num` int NOT NULL COMMENT '团队数量',
  `team_commission` decimal(12,2) NOT NULL COMMENT '团长佣金',
  `status` int NOT NULL DEFAULT '0' COMMENT '商品拼团状态 0=拼团中 1=拼团成功 2=拼团失败',
  `sno` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '平台成功后的订单号',
  `is_settlement` int NOT NULL DEFAULT '0' COMMENT '是否已结算',
  `add_date` timestamp NOT NULL COMMENT '添加时间',
  `end_date` timestamp NOT NULL COMMENT '拼团结束时间',
  `update_date` timestamp NULL DEFAULT NULL COMMENT '修改时间',
  `recycle` int NOT NULL DEFAULT '0' COMMENT '删除标识',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=147 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='开团表';
/*!40101 SET character_set_client = @saved_cs_client */;

