--
-- Table structure for table `lkt_guide_menu`
--

DROP TABLE IF EXISTS `lkt_guide_menu`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `lkt_guide_menu` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `store_id` int DEFAULT '0' COMMENT '商城ID',
  `role_id` int DEFAULT '0' COMMENT '角色ID',
  `menu_id` int DEFAULT '0' COMMENT '菜单ID',
  `is_display` tinyint DEFAULT '1' COMMENT '是否显示 0.不显示 1.显示',
  `guide_sort` int DEFAULT '0' COMMENT '导览排序',
  `add_date` timestamp NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '添加时间',
  `lang_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT 'zh_CN' COMMENT '语言',
  `country_num` int DEFAULT '156' COMMENT '国家语种默认156',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `id` (`id`) USING BTREE,
  KEY `menu_id` (`menu_id`) USING BTREE,
  KEY `role_id` (`role_id`) USING BTREE,
  KEY `menu_id_idx` (`menu_id`) USING BTREE,
  KEY `role_id_idx` (`role_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=116942 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='导览菜单';
/*!40101 SET character_set_client = @saved_cs_client */;

