  `add_date` timestamp NULL DEFAULT NULL COMMENT '发送消息时间',
  `is_read` int DEFAULT '0' COMMENT '是否已读  0 否 1 是',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=258 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='在线信息表';
