  `ali_out_request_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '支付宝退款请求号',
  `p_id` int NOT NULL COMMENT '订单详情ID',
  `re_type` tinyint(1) NOT NULL DEFAULT '0' COMMENT '退款类型 1:退货退款  2:退款 3:换货',
  `content` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '售后原因',
  `re_apply_money` decimal(12,2) DEFAULT '0.00',
  `re_money` decimal(12,2) DEFAULT '0.00',
  `real_money` decimal(12,2) DEFAULT '0.00',
